 19| 
 20| import java.io.File;
 21| import java.util.Date;
 22| import java.util.LinkedHashMap;
 23| import java.util.zip.ZipException;
 24| import org.apache.commons.compress.archivers.ArchiveEntry;
 25| 
 26| /**
 27|  * Extension that adds better handling of extra fields and provides
 28|  * access to the internal and external file attributes.
 29|  *
 30|  * @NotThreadSafe
 31|  */
 32| public class ZipArchiveEntry extends java.util.zip.ZipEntry
 33|     implements ArchiveEntry, Cloneable {
 34| 
 35|     public static final int PLATFORM_UNIX = 3;
 36|     public static final int PLATFORM_FAT  = 0;
 37|     private static final int SHORT_MASK = 0xFFFF;
 38|     private static final int SHORT_SHIFT = 16;
 39| 
 40|     /**
 41|      * The {@link java.util.zip.ZipEntry} base class only supports
 42|      * the compression methods STORED and DEFLATED. We override the
 43|      * field so that any compression methods can be used.
 44|      * <p>
 45|      * The default value -1 means that the method has not been specified.
 46|      *
 47|      * @see <a href="https://issues.apache.org/jira/browse/COMPRESS-93"
 48|      *        >COMPRESS-93</a>
 49|      */
 50|     private int method = -1;
 51| 
 52|     private int internalAttributes = 0;
 53|     private int platform = PLATFORM_FAT;
 54|     private long externalAttributes = 0;
 55|     private LinkedHashMap/*<ZipShort, ZipExtraField>*/ extraFields = null;
 56|     private String name = null;
 57| 
 58|     /**
 59|      * Creates a new zip entry with the specified name.
 60|      * @param name the name of the entry
 61|      */
 62|     public ZipArchiveEntry(String name) {
 63|         super(name);
 64|     }
 65| 
 66|     /**
 67|      * Creates a new zip entry with fields taken from the specified zip entry.
 68|      * @param entry the entry to get fields from
 69|      * @throws ZipException on error
 70|      */
 71|     public ZipArchiveEntry(java.util.zip.ZipEntry entry) throws ZipException {
 72|         super(entry);
 73|         setName(entry.getName());
 74|         byte[] extra = entry.getExtra();
 75|         if (extra != null) {
 76|             setExtraFields(ExtraFieldUtils.parse(extra));
 77|         } else {
 78|             // initializes extra data to an empty byte array
 79|             setExtra();
 80|         }
 81|         setMethod(entry.getMethod());
 82|     }
 83| 
 84|     /**
 85|      * Creates a new zip entry with fields taken from the specified zip entry.
 86|      * @param entry the entry to get fields from
 87|      * @throws ZipException on error
 88|      */
 89|     public ZipArchiveEntry(ZipArchiveEntry entry) throws ZipException {
 90|         this((java.util.zip.ZipEntry) entry);
 91|         setInternalAttributes(entry.getInternalAttributes());
 92|         setExternalAttributes(entry.getExternalAttributes());
 93|         setExtraFields(entry.getExtraFields());
 94|     }
 95| 
 96|     /**
 97|      */
 98|     protected ZipArchiveEntry() {
 99|         this("");
100|     }
101| 
102|     public ZipArchiveEntry(File inputFile, String entryName) {
103|         this(inputFile.isDirectory() && !entryName.endsWith("/") ? 
104|              entryName + "/" : entryName);
105|         if (inputFile.isFile()){
106|             setSize(inputFile.length());
107|         }
108|         setTime(inputFile.lastModified());
109|         // TODO are there any other fields we can set here?
110|     }
111| 
112|     /**
113|      * Overwrite clone.
114|      * @return a cloned copy of this ZipArchiveEntry
115|      */
116|     public Object clone() {
117|         ZipArchiveEntry e = (ZipArchiveEntry) super.clone();
118| 
119|         e.extraFields = extraFields != null ? (LinkedHashMap) extraFields.clone() : null;
120|         e.setInternalAttributes(getInternalAttributes());
121|         e.setExternalAttributes(getExternalAttributes());
122|         e.setExtraFields(getExtraFields());
123|         return e;
124|     }
125| 
126|     /**
127|      * Checks whether the compression method of this entry is supported,
128|      * i.e. whether the content of this entry can be accessed.
129|      *
130|      * @since Commons Compress 1.1
131|      * @see <a href="https://issues.apache.org/jira/browse/COMPRESS-93"
132|      *         >COMPRESS-93</a>
133|      * @return <code>true</code> if the compression method is known
134|      *         and supported, <code>false</code> otherwise
135|      */
136|     public boolean isSupportedCompressionMethod() {
137|         return method == STORED || method == DEFLATED;
138|     }
139| 
140|     /**
141|      * Returns the compression method of this entry, or -1 if the
142|      * compression method has not been specified.
143|      *
144|      * @return compression method
145|      */
146|     public int getMethod() {
147|         return method;
148|     }
149| 
150|     /**
151|      * Sets the compression method of this entry.
152|      *
153|      * @param method compression method
154|      */
155|     public void setMethod(int method) {
156|         if (method < 0) {
157|             throw new IllegalArgumentException(
158|                     "ZIP compression method can not be negative: " + method);
159|         }
160|         this.method = method;
161|     }
162| 
163|     /**
164|      * Retrieves the internal file attributes.
165|      *
166|      * @return the internal file attributes
167|      */
168|     public int getInternalAttributes() {
169|         return internalAttributes;
170|     }
171| 
172|     /**
173|      * Sets the internal file attributes.
174|      * @param value an <code>int</code> value
175|      */
176|     public void setInternalAttributes(int value) {
177|         internalAttributes = value;
178|     }
179| 
180|     /**
181|      * Retrieves the external file attributes.
182|      * @return the external file attributes
183|      */
184|     public long getExternalAttributes() {
185|         return externalAttributes;
186|     }
187| 
188|     /**
189|      * Sets the external file attributes.
190|      * @param value an <code>long</code> value
191|      */
192|     public void setExternalAttributes(long value) {
193|         externalAttributes = value;
194|     }
